/* -----------------------------------------------------------------------
 * encoder_sm.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * BJT2 Sound Modulating Toy — Rotary Encoder State Machine
 * Author: Tony (Display/UI subsystem)
 *
 * Quadrature decode table for the Bourns PEC12R (12 PPR).
 * At rest between detents both pins are high (A=1, B=1).
 *
 * Clockwise sequence (one full detent):
 *   State      A  B
 *   IDLE       1  1   <- resting position
 *   CW_1       0  1   <- A falls first going CW
 *   CW_2       0  0   <- B falls
 *   CW_3       1  0   <- A rises
 *   -> fires EVENT_VOLUME_UP, returns to IDLE (B rises back to 1)
 *
 * Counter-clockwise sequence (one full detent):
 *   State      A  B
 *   IDLE       1  1
 *   CCW_1      1  0   <- B falls first going CCW
 *   CCW_2      0  0   <- A falls
 *   CCW_3      0  1   <- B rises
 *   -> fires EVENT_VOLUME_DOWN, returns to IDLE (A rises back to 1)
 *
 * Any pin combination that doesn't match the expected next step is
 * ignored — the state machine stays where it is. This rejects single
 * contact bounces without needing a hardware debounce capacitor.
 *
 * In words: each state remembers how far through one click the knob is.
 * Clockwise, A drops first, then B drops, then A comes back up; when B
 * comes back up too, the click is complete and EVENT_VOLUME_UP fires
 * once. Counter-clockwise is the same with A and B swapped. From the
 * first two steps, the pattern of the step before (a bounce, or the user
 * turning back) moves the state back too. The third step (CW_3, CCW_3)
 * only waits for the rest pattern 1 1.
 *
 * No task of its own, and the firmware no longer calls it: TIM3 decodes
 * the knob in hardware (encoder_sm.h says why). The host tests run it.
 * ----------------------------------------------------------------------- */

#include "encoder_sm.h"
#include <stddef.h>

/* -----------------------------------------------------------------------
 * encoder_sm_init
 * ----------------------------------------------------------------------- */
void encoder_sm_init(encoder_sm_t *enc)
{
    if (enc == NULL) {
        return;
    }
    enc->state = ENC_STATE_IDLE;
}

/* -----------------------------------------------------------------------
 * encoder_sm_update
 * The transition table is implemented as a switch on current state,
 * with nested checks on the pin values expected for the next valid step.
 * ----------------------------------------------------------------------- */
ui_event_t encoder_sm_update(encoder_sm_t *enc, encoder_pins_t pins)
{
    if (enc == NULL) {
        return EVENT_NONE;
    }

    bool a = pins.pin_a;
    bool b = pins.pin_b;

    switch (enc->state) {

        case ENC_STATE_IDLE:
            /* Resting state — both pins high.
             * A falling first means clockwise; B falling first means CCW. */
            if (!a && b)  { enc->state = ENC_STATE_CW_1; }
            else if (a && !b) { enc->state = ENC_STATE_CCW_1; }
            /* Both low from idle is ambiguous — ignore */
            break;

        case ENC_STATE_CW_1:
            /* Expecting A=0, B=0 next for CW */
            if (!a && !b) {
                enc->state = ENC_STATE_CW_2;
            } else if (a && b) {
                /* Bounced back to idle */
                enc->state = ENC_STATE_IDLE;
            }
            break;

        case ENC_STATE_CW_2:
            /* Expecting A=1, B=0 next for CW */
            if (a && !b) {
                enc->state = ENC_STATE_CW_3;
            } else if (!a && b) {
                /* Reversed — go back */
                enc->state = ENC_STATE_CW_1;
            }
            break;

        case ENC_STATE_CW_3:
            /* Final step — A=1, B=1 completes the detent */
            if (a && b) {
                enc->state = ENC_STATE_IDLE;
                return EVENT_VOLUME_UP;
            }
            break;

        case ENC_STATE_CCW_1:
            /* Expecting A=0, B=0 next for CCW */
            if (!a && !b) {
                enc->state = ENC_STATE_CCW_2;
            } else if (a && b) {
                enc->state = ENC_STATE_IDLE;
            }
            break;

        case ENC_STATE_CCW_2:
            /* Expecting A=0, B=1 next for CCW */
            if (!a && b) {
                enc->state = ENC_STATE_CCW_3;
            } else if (a && !b) {
                enc->state = ENC_STATE_CCW_1;
            }
            break;

        case ENC_STATE_CCW_3:
            /* Final step — A=1, B=1 completes the detent */
            if (a && b) {
                enc->state = ENC_STATE_IDLE;
                return EVENT_VOLUME_DOWN;
            }
            break;

        default:
            enc->state = ENC_STATE_IDLE;
            break;
    }

    return EVENT_NONE;
}
